BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (199::BIGINT, 'El profe cae super bien; y no es su culpa que el curso sea tan pesado. Pero muchas veces en clase se va por las ramas y termina haciendo un enredo. Preste atención por que si no, se pierde.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2026-08-06T00:00:00+00:00'::TIMESTAMPTZ, '9fca99ea8a5fdb6445d644b4c64aa679368c167c8916d9d96182496022eb2b04'::TEXT, ARRAY[3257]::BIGINT[]),
    (199::BIGINT, 'Es bastante gracioso, pero se desvía mucho del tema. Explica haciendo muchos ejercicios. Califica bastante suave y hasta da puntos al final si los necesita. Para nada es un mal profe pero yo no lo recomendaría ya que siento que hay otros profes más buenos. Una palabra: Fregado'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, '017e6c252df8961b81b04fd1cc1104815dfbe7b1fd8522b9ad12e060ea9d6bae'::TEXT, ARRAY[604]::BIGINT[]),
    (199::BIGINT, 'Muy buen profesor que además de explicar bien no califica tan fuerte. No voy a mentir que física si es un curso jodido que hay que poner, no obstante, él hace lo posible para que pases y podas entender.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, '2c274c27c59b9850feb55a6e9f0d68a468c94f95395adbed917aa91e42c3f08c'::TEXT, ARRAY[604]::BIGINT[]),
    (199::BIGINT, 'Vale totalmente la pena matricular con él. Se explica perfectamente, y tiene todo el gusto de explicarle hasta lo más básico. Además que hace las clases, cuando puede, dinámicas y divertidas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-05T00:00:00+00:00'::TIMESTAMPTZ, 'ab89bd629127e129e5df9158d8041f391349809d38e0809e00be467d1cf235fa'::TEXT, ARRAY[604]::BIGINT[]),
    (199::BIGINT, 'El profe Dennis es bastante amable calificando y reconoce el esfuerzo. Hace muchos ejercicios pero explica algo rápido, así que hay que estar poniendo bastante atención, por lo que apuntar a veces es difícil, y por la dificultad del curso sí hay que dedicarle estudio independiente. Recomendado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'f52f2824c2b13316e6afa15f281b6101dc920a6e2b8f4bb3ad0a3f2bba2ae4fe'::TEXT, ARRAY[604]::BIGINT[]),
    (199::BIGINT, 'El profe es muy buena nota, califica procedimiento y tiene compasión al revisar, si necesitará de unos puntos el profe hace el esfuerzo para ayudarle, eso si vaya a clases para que el profe lo conozca. Eso sí, prepárese para escribir que todo lo apunta en la pizarra y va rápido explicando.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '7d90da50204cf7ffe6d4362ffa3893fd3d8660a4c77e3a3be5326e353bc1649b'::TEXT, ARRAY[604]::BIGINT[]),
    (199::BIGINT, 'Ayuda muchísimo si él ve que usted participa y le interesa la clase, no hace quices, deja proyectos en los que se gana muy fácil el porcentaje si se hace de forma ordenada. Califica suave y toma en cuenta puntos de procedimiento y explicaciones.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'dd6e8db50d09d4b1d58375e7132f5df9ee178b8807cb945fd1c87880be15a506'::TEXT, ARRAY[604]::BIGINT[]),
    (199::BIGINT, 'El mae sabe de lo que habla. Esresponsable con la clases. Lo recomiendo si ud es una persona que no necesita hacer preguntas seguido para entender, porque para tareas y proyectos el mae a veces lo deja a uno más enredado que lo que llegó antes de preguntar. Muchas veces responde correos 2 días dsp.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Exámenes retadores']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'd522398fea2eeaa57be6cfd142e0ddfe053f5d3e63de54d825ef18914df2c9a7'::TEXT, ARRAY[604, 922, 1369]::BIGINT[]),
    (199::BIGINT, 'A este profe se le agarra mucho cariño muy facilmente, es super divertido, explica bien y cualquier duda con gusto le ayuda. Es justo calificando y es medio complicado que regale puntos, pero en general Física III es muy facil.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'b6c5922aa64f7de9518154ff5a9efe8c2fbe08779b42e329bc2342b9b0fe3c2c'::TEXT, ARRAY[922]::BIGINT[]),
    (199::BIGINT, 'El mae es una teja, lleve Fiscia 1 y 3 con el, y al final si usted le pone, o bromea con el en clases, lo ayuda mucho. Lo super recomiendo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'dc31c53a6c31d47f62d5788aa011abeac730900121f6274543d68463035ade03'::TEXT, ARRAY[604]::BIGINT[]),
    (199::BIGINT, 'Es un profe regular casi bueno, como punto en contra, a veces se mete a explicar algunas demostraciones un poco engorrosas que pueden confundir y en otras ocasiones hace ejercicios en los que él mismo se equivoca pero por lo demás bien. Clases al grano, claro, bastantes ejemplos y es buena persona.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '613d8692bc742617b2b1e3ae906350fd0eebea8d490e5170081bd941b54f32fb'::TEXT, ARRAY[922]::BIGINT[]),
    (199::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '31ab022ea397bd5246bfb99f94208cd2df277919ff7cde892ad493ea0c2b44c2'::TEXT, ARRAY[4122]::BIGINT[]),
    (199::BIGINT, 'No le entendí nunca, los ejercicios que hace en clase parece que se los tiene memorizados y solo va narrando, pero se pasa fácil, a veces tira datos interesantes de la materia con relación a la vida cotidiana'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'bf2c4b8458996a20d0238906d463b94762a5c3355413a80c99768b4139c3e42d'::TEXT, ARRAY[922]::BIGINT[]),
    (199::BIGINT, 'Física es muy pesado para algunas personas, sin embargo, Dennis brinda mucha ayuda y explica las veces que haya que explicar. Sus clases no son largas y hace que la materia sea llevadera. Es muy buena gente, es vacilón.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-10T00:00:00+00:00'::TIMESTAMPTZ, '9acda31e8f201e6e5b500d279ceb0400c5d19789045fe8c21bedd265d48f4e35'::TEXT, ARRAY[604]::BIGINT[]),
    (199::BIGINT, 'El curso como tal es difícil, los examenes son realmente duros, pero eso es cosa de catedra, Dennis es super divertido y hace las clases poco aburridas, da bastantes ejemplos, pero hay que ponerle atención.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, '5baadb32930124496dcf69d6e7c58c573dbdfc16168610480b5629927bd1122b'::TEXT, ARRAY[604]::BIGINT[]),
    (199::BIGINT, 'Es una gran persona, muy cómico y abierto a ayudar. Eso sí, sus clases (al menos las presenciales) son muy rápidas, y se basan en ver muchos ejemplos. Si le sigue el ritmo, aprende bastante. Complemente con lo que pone la cátedra y haga ejercicios a consciencia. Es un curso relativamente fácil.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2022-11-30T00:00:00+00:00'::TIMESTAMPTZ, '41e561a38e13e4ec47809383d8a2ce04df5c1e928a01938eb901a9a8420a1897'::TEXT, ARRAY[604]::BIGINT[]),
    (199::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'b3e636ba999def57a6238418aef816f870dada4d586796ae5ca59dc208a5aa71'::TEXT, ARRAY[604]::BIGINT[]),
    (199::BIGINT, 'Pura vida pero nada más, no vale la pena invertir tiempo en calificar una clase tan aburrida y sin sentido como la de Dennis Murillo, alguien que le explique que en física hay números y fórmulas. Si mi evaluación no les ha explicado nada es porque la hice a la imagen y semejanza de sus clases.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2022-10-09T00:00:00+00:00'::TIMESTAMPTZ, '7b5ef9118b792c8b98485b1b5a5f2946393422428fbadf5f4f96dcb509cf3b6b'::TEXT, ARRAY[604]::BIGINT[]),
    (199::BIGINT, 'Sabe mucho pero es muy desordenado explicando, a veces resuelve ejercicios sin decir cual es el enunciado y cuesta seguir el hilo de la clase.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'bac203118d09a275ed82aeaecec86d0f91b7ab3bdae1013e3c8b194759f5ba48'::TEXT, ARRAY[1369]::BIGINT[]),
    (199::BIGINT, 'Creo que los mejores profesores de TEC, siempre buena gente y atento. Cuando ocupas ayuda el te la da y creo que es algo muy bueno. Ninguna queja. Si puede matricule con el.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2022-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'ddf08a9415b6ebb2692b70e1d17859c04a37d9c3eec30ad257d3b020c67d639e'::TEXT, ARRAY[1369]::BIGINT[]),
    (199::BIGINT, 'En virtual puede ocurrir que avanza muy rápido con las presentaciones, o que a veces están muy cargadas, pero como profe y explicando y haciendo ejemplos es excelente. Además, en presencial sé que es mucho más ordenado y que la clase se entiende un 200%.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2022-05-28T00:00:00+00:00'::TIMESTAMPTZ, '2ea578bfa7535a7f3c30e86022723f8fdfc22c049b79d5c1e400fdcc6c4f1ca9'::TEXT, ARRAY[1369]::BIGINT[]),
    (199::BIGINT, 'Muy buen profe, explica bien los contenidos del curso y vuelve la clase interesante. De forma virtual y al ser tanto el contenido del curso puede volverse difícil seguir el hilo de las clases, el profe intenta hacerlas compactas y concisas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'd53a2bc3f535ae029da0aab27bf7e7509e2cd67c7e1a96da89d8179474c4e68d'::TEXT, ARRAY[1369]::BIGINT[]),
    (199::BIGINT, 'A pesar de que el curso es complicado, se ve rápido y es denso, el profe hace lo posible por hacerle saber a todos qué es lo que va a evaluar, las clases son realmente interesantes y siempre está apto a responder preguntas, excelente profesor'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros']::TEXT[], '2022-05-26T00:00:00+00:00'::TIMESTAMPTZ, 'b6f14e9b76c0063bd19c27add81180c100a7a2a8f2bade3f5868ae5a946642f3'::TEXT, ARRAY[1369]::BIGINT[]),
    (199::BIGINT, 'El profe explica bien los conceptos del curso. Además, es flexible con la fecha de entrega de trabajos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-05-26T00:00:00+00:00'::TIMESTAMPTZ, '9e283c12b86e7a3c3c7e87a397d6fd9b8a97f005de8147e2df72562f7d3836ed'::TEXT, ARRAY[1369]::BIGINT[]),
    (199::BIGINT, 'Matricule con este profe es buena nota'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2022-05-26T00:00:00+00:00'::TIMESTAMPTZ, '440d6d8ffcd38316df7fb7dda4a06163bdb635a3326c4dc7cf51d8df247d81a6'::TEXT, ARRAY[1369]::BIGINT[]),
    (199::BIGINT, 'Es muy pura vida y acepta cuando hay errores en evaluaciones. Responde rápido. Hace muchos ejemplos y demostraciones de fórmulas que suele incluir en quices. Todas las tareas son bastante largas pero son solo 5 en todo el semestre, no muy complejas y casi todo se hace grupal así que busque compas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '9159d7d9af965d476f9862293912c4621cd07806684a8edde77b820175e0bff0'::TEXT, ARRAY[1369]::BIGINT[]),
    (199::BIGINT, 'Es buena nota y hace muchos ejemplos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, '99a182cf8810d722e805b8d9c83c4dbdcdee6a72b30eedc5a84f0e1d34579e64'::TEXT, ARRAY[604]::BIGINT[]),
    (199::BIGINT, 'Virtual es muy accesible, da 2 clases sincrónicas semanales. Resuelve muchos ejercicios durante la clase, muy accesible, explica bien y aclara dudas. Califica suave'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2021-02-18T00:00:00+00:00'::TIMESTAMPTZ, 'a93b27c3cf93895cb8b299d2c4a2d5ae962376fb5c526e47b8075232525ef4de'::TEXT, ARRAY[604]::BIGINT[]),
    (199::BIGINT, 'Lo llevé virtual! Durante las clases presenciales fue claro explicando, muy buena gente. Sin embargo, no recibí ni una clase virtual con él, pero siempre hacía consulta, resolvía dudas y ejercicios.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'dd88c9b14dce5349780fa9a7d5413f6b5e867d7e26c12eebd267b39e8d82fe1d'::TEXT, ARRAY[604]::BIGINT[]),
    (199::BIGINT, 'Es super buena gente,justo para calificar y lo ayuda a uno a lo largo de las practicas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-04T00:00:00+00:00'::TIMESTAMPTZ, '4f51cbf9186de88f39c305215e025f14488cc0a150a220ac3076ff4dd2740dce'::TEXT, ARRAY[604]::BIGINT[]),
    (199::BIGINT, 'Excelente profesor, explica lo justo y necesario. Es bastante pura vida, su actitud hace del laboratorio una experiencia amena, recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-23T00:00:00+00:00'::TIMESTAMPTZ, 'db339b80d8a84ec2b4be05a7dfa7944f6320b62da0c976444c8eab7abda1e023'::TEXT, ARRAY[631, 607]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
